def hazel_prompt(mode):
    head = _HAZEL_HEAD
    if mode == "app":
        head = head.replace(_RULE1_WEBSITE, _RULE1_APP)
    return head + "\n\n" + _LIBRARY.format(toc=table_of_contents(mode)) + "\n\n" + _HAZEL_TAIL
